#!/usr/bin/env python3
"""Preserve composed superscript and subscript on AI import."""
import sys
from pathlib import Path

path = Path(sys.argv[1]) / "crates/eps/src/import/ate.rs"
source = path.read_text(encoding="utf-8")
replacements = [
    ("    CharStyle, HyphenationOptions,", "    CharPosition, CharStyle, HyphenationOptions,"),
    ("    PathEffect, TabAlign, TabStop, TextKind, TextObject, TextRun,", "    PathEffect, ScriptMetrics, TabAlign, TabStop, TextKind, TextObject, TextRun,"),
    ("    baseline_shift: f64,\n    h_scale:", "    baseline_shift: f64,\n    position: CharPosition,\n    h_scale:"),
    ("            baseline_shift: num(\"9\").filter(|v| v.abs() < 1e5).unwrap_or(0.0),", "            baseline_shift: num(\"9\").filter(|v| v.abs() < 1e5).unwrap_or(0.0),\n            position: CharPosition::Normal,"),
    ("        baseline_shift: s.baseline_shift * scale,", "        baseline_shift: s.baseline_shift * scale,\n        position: s.position,"),
    ("                    baseline_shift: 0.0,\n                    h_scale:", "                    baseline_shift: 0.0,\n                    position: CharPosition::Normal,\n                    h_scale:"),
    ("        if let Some(f) = view.get(\"2\").and_then(|l| find_node(l, \"F\")) {", "        let layout = view.get(\"2\").and_then(|l| find_node(l, \"F\"));\n        if let Some(f) = layout {"),
    ("        let mut budget = MAX_STORY_TABS;\n        let mut tabs_left_out = false;\n        for (_, p) in &mut paras {", "        if !vertical && matches!(frames.as_slice(), [FrameKind::Point(_)]) && let Some(layout) = layout {\n            apply_script_positions(layout, &mut runs, text.chars().count());\n        }\n        let mut budget = MAX_STORY_TABS;\n        let mut tabs_left_out = false;\n        for (_, p) in &mut paras {"),
    ("/// A point of the canvas (y down)", "/// The composed glyph runs carry the applied script scale and signed shift. They can\n/// split a character style run (for example, the \"th\" in an ordinal).\nfn apply_script_positions(layout: &Val, runs: &mut Vec<(usize, Style)>, count: usize) {\n    let mut glyph_runs = Vec::new();\n    find_nodes(layout, \"G\", &mut glyph_runs);\n    let mut composed = Vec::new();\n    for glyph_run in glyph_runs {\n        let Some(styles) = glyph_run.get(\"10\") else { return };\n        let (attrs, lengths) = (styles.get(\"0\").map(Val::list), styles.get(\"1\").map(Val::list));\n        let (Some(attrs), Some(lengths)) = (attrs, lengths) else { return };\n        if attrs.len() != lengths.len() { return; }\n        for (attr, len) in attrs.iter().zip(lengths) {\n            let Some(len) = len.num().filter(|n| *n > 0.0 && *n <= count as f64 && n.fract() == 0.0) else { return };\n            let metrics = attr.get(\"2\").and_then(Val::nums).zip(attr.get(\"5\").and_then(Val::num)).and_then(|(scales, rise)| {\n                let &[x, y] = scales.as_slice() else { return None };\n                ((0.01..=5.0).contains(&x) && (x - y).abs() < 1e-6 && rise.abs() < 1e5).then_some((x, rise))\n            });\n            composed.push((len as usize, metrics));\n        }\n    }\n    if composed.is_empty() || composed.iter().all(|(_, metrics)| metrics.is_none()) || composed.iter().fold(0usize, |total, (len, _)| total.saturating_add(*len)) != count {\n        return;\n    }\n    let mut adjusted = Vec::new();\n    let mut original = runs.iter();\n    let Some((remaining, mut ref_style)) = original.next() else { return };\n    let mut remaining = *remaining;\n    for (mut len, metrics) in composed {\n        while len > 0 {\n            while remaining == 0 {\n                let Some((n, style)) = original.next() else { return };\n                remaining = *n;\n                ref_style = style;\n            }\n            let take = remaining.min(len);\n            let mut style = (*ref_style).clone();\n            if let Some((factor, rise)) = metrics {\n                let percent = rise.abs() / style.size * 100.0;\n                if percent <= 500.0 {\n                    let m = ScriptMetrics { size: factor * 100.0, position: percent };\n                    style.position = if rise >= 0.0 { CharPosition::Superscript(m) } else { CharPosition::Subscript(m) };\n                }\n            }\n            adjusted.push((take, style));\n            remaining -= take;\n            len -= take;\n        }\n    }\n    *runs = adjusted;\n}\n\n/// A point of the canvas (y down)"),
    ("    /// A point-type story of `text`", "\n    #[test]\n    fn leo_ai_composed_script_keeps_its_size_and_baseline() {\n        let mut s = story(\"abcd\\r\", &[0.0], &Para::default());\n        let layout = read(b\"/0 [ << /99 /G /10 << /0 [ << >> << /2 [ 0.5 0.5 ] /5 4 >> << /2 [ 0.6 0.6 ] /5 -2 >> << >> ] /1 [ 1 1 1 2 ] >> >> ]\").unwrap();\n        apply_script_positions(&layout, &mut s.runs, 5);\n        let n = s.node(NodeId(1), 0, (0.0, 0.0), Affine::IDENTITY).unwrap();\n        let NodeKind::Text(t) = n.kind else { panic!(\"expected editable text\") };\n        let result: Vec<_> = t.runs.iter().map(|r| (r.text.as_str(), r.style.position.scale_shift(r.style.size))).collect();\n        assert_eq!(result.len(), 4);\n        for ((text, (scale, rise)), (want, factor, shift)) in result.into_iter().zip([\n            (\"a\", 1.0, 0.0), (\"b\", 0.5, 4.0), (\"c\", 0.6, -2.0), (\"d\", 1.0, 0.0)\n        ]) {\n            assert_eq!(text, want);\n            assert!((scale - factor).abs() < 1e-9 && (rise - shift).abs() < 1e-9);\n        }\n    }\n\n    /// A point-type story of `text`"),
]
for old, new in replacements:
    if source.count(old) != 1:
        raise SystemExit(f"Unexpected AI text importer source: {old[:80]}")
    source = source.replace(old, new, 1)
path.write_text(source, encoding="utf-8", newline="\n")
